#[repr(C)]
struct PushRange {
    stage_flags: u32,
    offset: u32,
    size: u32,
}

fn read_spv(env_var: &str) -> Vec<u32> {
    let path = std::env::var(env_var).expect("missing shader path env var");
    let raw = fs::read(&path).expect("read spv");
    assert_eq!(raw.len() % 4, 0);
    raw.chunks_exact(4)
        .map(|c| u32::from_le_bytes([c[0], c[1], c[2], c[3]]))
        .collect()
}

fn compile_bytes(
    frozen: &FrozenGm20b,
    spv: &[u32],
    stage_bit: u32,
    bindings: &[SwitchNakBinding],
    push: Option<&PushRange>,
) -> Result<Vec<u8>, i32> {
    let entry = b"main\0";
    let set = SwitchNakSet {
        bindings: bindings.as_ptr(),
        binding_count: bindings.len() as u32,
        flags: 0,
    };
    let layout = SwitchNakLayout {
        sets: if bindings.is_empty() { null() } else { &set },
        set_count: u32::from(!bindings.is_empty()),
        create_flags: 0,
        push_ranges: push.map_or(null(), |p| p as *const PushRange as *const c_void),
        push_range_count: u32::from(push.is_some()),
    };
    let info = SwitchNvkStageInfo {
        spirv: spv.as_ptr(),
        spirv_bytes: spv.len() * size_of::<u32>(),
        entry: entry.as_ptr() as *const c_char,
        stage: stage_bit,
        specialization: null(),
        layout: 0,
        pipeline_flags: 0,
        pipeline_pnext: null(),
        stage_pnext: null(),
        sample_shading: false,
        split: false,
        half_targets: 0,
        const_push_mask: 0,
        const_push_words: [0; 32],
        center_frag_depth: 0,
        semantic: null(),
        portable_context: null(),
        portable: None,
        texs_f16: false,
        turned: false,
        xr_plane_bindings: [0; 6],
        unorm_targets: 0,
    };
    let mut stage: SwitchNvkStage = unsafe { zeroed() };
    let rc = unsafe { switch_compile_stage(frozen.0.as_ptr() as *const c_void, &info, &layout, &mut stage) };
    if rc != VK_SUCCESS {
        return Err(rc);
    }
    let mut out = stage.header.to_vec();
    let code = unsafe { std::slice::from_raw_parts(stage.code as *const u8, stage.code_bytes as usize) };
    out.extend_from_slice(code);
    unsafe {
        switch_compile_stage_finish(&mut stage);
    }
    Ok(out)
}

#[test]
fn concurrent_cold_and_warm_render_and_compute_compiles() {
    let vert = Arc::new(read_spv("PARITY_VERT_SPV"));
    let comp = Arc::new(read_spv("PARITY_COMP_SPV"));
    let threads = 8usize;
    let rounds = 4usize;
    let barrier = Arc::new(Barrier::new(threads));

    let mut handles = Vec::with_capacity(threads);
    for tid in 0..threads {
        let vert = Arc::clone(&vert);
        let comp = Arc::clone(&comp);
        let barrier = Arc::clone(&barrier);
        handles.push(std::thread::spawn(move || {
            let local_frozen = FROZEN_GM20B;
            let vert_binds = [SwitchNakBinding {
                binding: 0,
                ty: 6,
                count: 1,
                flags: 0,
                offset: 0,
                stride: 16,
            }];
            let comp_binds = [
                SwitchNakBinding {
                    binding: 0,
                    ty: 7,
                    count: 1,
                    flags: 0,
                    offset: 0,
                    stride: 16,
                },
                SwitchNakBinding {
                    binding: 1,
                    ty: 7,
                    count: 1,
                    flags: 0,
                    offset: 16,
                    stride: 16,
                },
            ];
            let comp_push = PushRange {
                stage_flags: VK_SHADER_STAGE_COMPUTE_BIT,
                offset: 0,
                size: 8,
            };
            let mut results = Vec::with_capacity(rounds);
            for round in 0..rounds {
                // Cold simultaneous entry on round 0, repeated warm contention on rounds 1..rounds.
                barrier.wait();
                let is_vert = (tid + round) % 2 == 0;
                let bytes = if is_vert {
                    compile_bytes(&local_frozen, &vert, VK_SHADER_STAGE_VERTEX_BIT, &vert_binds, None)
                        .expect("vertex compile")
                } else {
                    compile_bytes(
                        &local_frozen,
                        &comp,
                        VK_SHADER_STAGE_COMPUTE_BIT,
                        &comp_binds,
                        Some(&comp_push),
                    )
                    .expect("compute compile")
                };
                results.push((is_vert, bytes));
            }
            results
        }));
    }

    let mut want_vert: Option<Vec<u8>> = None;
    let mut want_comp: Option<Vec<u8>> = None;
    for h in handles {
        for (is_vert, bytes) in h.join().expect("worker panicked") {
            assert!(!bytes.is_empty());
            let slot = if is_vert { &mut want_vert } else { &mut want_comp };
            if let Some(expected) = slot {
                assert_eq!(&bytes, expected);
            } else {
                *slot = Some(bytes);
            }
        }
    }

    let mut mutated = FROZEN_GM20B;
    mutated.0[14] ^= 0x01;
    let vert_binds = [SwitchNakBinding {
        binding: 0,
        ty: 6,
        count: 1,
        flags: 0,
        offset: 0,
        stride: 16,
    }];
    let mismatch = compile_bytes(&mutated, &vert, VK_SHADER_STAGE_VERTEX_BIT, &vert_binds, None);
    assert!(mismatch.is_err(), "mismatched frozen device info must fail");
}
